{"source":"import odoolib
# Read-only connection probe using conventional task-world endpoint credentials.
for args in [
    dict(hostname='odoo', database='odoo', login='admin', password='admin'),
    dict(hostname='localhost', database='odoo', login='admin', password='admin'),
]:
    try:
        c=odoolib.get_connection(**args)
        ok=c.check_login()
        print('PROBE',args['hostname'],'login',ok,'uid',c.user_id,'db',c.database)
        if ok:
            for model, domain, fields in [
              ('sale.order', [], ['name','state','partner_id','date_order','commitment_date','amount_total']),
              ('mrp.production', [], ['name','state','product_id','product_qty','origin']),
              ('purchase.order', [], ['name','state','partner_id','date_order','origin']),
              ('project.task', [], ['name','description','state','date_deadline']),
            ]:
                try:
                    rows=c.get_model(model).search_read(domain, fields, limit=100, order='id desc')
                    print('MODEL',model,'N',len(rows))
                    for r in rows: print(r)
                except Exception as e: print('MODEL_ERROR',model,type(e).__name__,str(e))
            break
    except Exception as e:
        print('PROBE_ERROR',args['hostname'],type(e).__name__,str(e))"}

